bool cuo__typed_readable(uint16_t type_id)
{
    const char *path = cuo_type_path(type_id);
    for (size_t i = 0; path && i < sizeof READABLE / sizeof *READABLE; i++)
        if (strcmp(path, READABLE[i]) == 0)
            return true;
    return false;
}

