const cuo_Hits *cuo_Hits_column(cuo_query q, size_t term)
{
    if (!q.len)
        return NULL;
    cuo_modding_components_list_hits_t l;
    cuo_modding_components_column_hits(cuo__typed_query(q), (uint8_t)term, &l);
    cuo_Hits *out = cuo_alloc((l.len ? l.len : 1) * sizeof *out);
    for (size_t i = 0; i < l.len; i++)
        from_Hits(&out[i], &l.ptr[i]);
    cuo_modding_components_list_hits_free(&l);
    return out;
}

